css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .66); position: relative; }
.loader .box { position: absolute; right: 4%; top: 20%; width: 34%; height: 52%; border-radius: 7px; background: linear-gradient(#475569, #1e293b); }
.loader .pencil { position: absolute; top: 38%; left: 2%; width: 62%; height: 16%; border-radius: 3px 0 0 3px; background: repeating-linear-gradient(90deg, var(--accent) 0 12%, var(--accent-2) 0 24%); animation: sharp-push calc(var(--loader-speed) * 1.5) ease-in-out infinite; }
.loader .crank { position: absolute; right: 1%; top: 43%; width: 15%; height: 7%; border-radius: 4px; background: var(--accent-2); transform-origin: 0% 50%; animation: sharp-crank calc(var(--loader-speed) * 1) linear infinite; }
.loader .crank::after { content: ''; position: absolute; left: 78%; top: -60%; width: 34%; height: 220%; border-radius: 3px; background: #94a3b8; }
.loader i { position: absolute; right: 20%; top: 70%; width: 9%; height: 9%; border-radius: 60% 6% 60% 6%; background: var(--accent-2); opacity: 0; animation: sharp-shave calc(var(--loader-speed) * 1.5) ease-in infinite; }
.loader i:nth-of-type(2) { right: 32%; animation-delay: calc(var(--loader-speed) * .5); }
@keyframes sharp-push { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(5%); } }
@keyframes sharp-crank { to { transform: rotate(1turn); } }
@keyframes sharp-shave { 0% { opacity: 0; transform: translateY(-30%) rotate(0deg); } 25% { opacity: 1; } 100% { opacity: 0; transform: translateY(140%) rotate(160deg); } }
